def get_divider_lines(grid):
    rows = len(grid)
    cols = len(grid[0])
    background = grid[0][0]
    h_lines = sorted([r for r in range(rows) if len(set(grid[r])) == 1 and background not in set(grid[r])])
    v_lines = sorted([c for c in range(cols) if len(set(grid[r][c] for r in range(rows))) == 1 and background not in set(grid[r][c] for r in range(rows))])
    return h_lines, v_lines

def find_region_specs(grid, h_lines, v_lines):
    """
    Returns a list of region specs based on divider lines.
    A region spec dict: {'type': 'h'/'v', 'start': index, 'end': index, 'name': 'left'/'right'/'top'/'bottom'/'between_X'...}
    """
    if h_lines:
        regions = []
        # Top region
        if h_lines[0] > 0:
            regions.append({'type': 'h', 'start': 0, 'end': h_lines[0] - 1, 'name': 'top'})
        # Between regions (for multiple h lines)
        for i in range(1, len(h_lines)):
            start = h_lines[i-1] + 1
            end = h_lines[i] - 1
            if start <= end:
                name = f"between_{i-1}"
                regions.append({'type': 'h', 'start': start, 'end': end, 'name': name})
        # Bottom region
        if h_lines[-1] < rows - 1:
            regions.append({'type': 'h', 'start': h_lines[-1] + 1, 'end': rows - 1, 'name': 'bottom'})
    elif v_lines:
        # Same for vertical
        regions = []
        if v_lines[0] > 0:
            regions.append({'type': 'v', 'start': 0, 'end': v_lines[0] - 1, 'name': 'left'})
        for i in range(1, len(v_lines)):
            start = v_lines[i-1] + 1
            end = v_lines[i] - 1
            if start <= end:
                name = f"between_{i-1}"
                regions.append({'type': 'v', 'start': start, 'end': end, 'name': name})
        if v_lines[-1] < cols - 1:
            regions.append({'type': 'v', 'start': v_lines[-1] + 1, 'end': cols - 1, 'name': 'right'})
    return regions

def count_region_unique(grid, region):
    """Count unique values in region (dict with type, start, end, name)"""
    st, end_val = region['start'], region['end']
    if region['type'] == 'h':
        # Horizontal regions: all columns in those rows
        return len(set(grid[r][c] for r in range(st, end_val + 1) for c in range(len(grid[0]))))
    else:
        # Vertical regions: all rows in those columns
        return len(set(grid[r][c] for r in range(len(grid)) for c in range(st, end_val + 1)))

def get_target_indices_region(grid, region):
    """Get list of indices (row or col) for each region"""
    st, end_val = region['start'], region['end']
    if region['type'] == 'h':
        return list(range(st, end_val + 1))
    else:
        return list(range(st, end_val + 1))

def transform(grid):
    rows = len(grid)
    cols = len(grid[0])
    result = [row[:] for row in grid]

    h_lines, v_lines = get_divider_lines(grid)

    # Check for vertical lines case
    if len(v_lines) >= 2:
        v_lines_sorted = sorted(v_lines)

        for r in range(rows):
            regions = []
            if v_lines_sorted[0] > 0:
                regions.append((0, v_lines_sorted[0] - 1, 'left'))
            for i in range(1, len(v_lines_sorted)):
                start = v_lines_sorted[i-1] + 1
                end = v_lines_sorted[i] - 1
                if start <= end:
                    regions.append((start, end, f"between_{i-1}"))
            if v_lines_sorted[-1] < cols - 1:
                regions.append((v_lines_sorted[-1] + 1, cols - 1, 'right'))

            if not regions:
                continue

            # Count unique for each region on this row
            region_uniques = []
            for st, en, name in regions:
                vals = set(result[r][st:en + 1])
                region_uniques.append((len(vals), st, en, name, result[r][st:en + 1]))

            region_uniques.sort(key=lambda x: x[0], reverse=True)
            best = region_uniques[0]

            # Copy best to all others
            for u in region_uniques:
                if u[3] == best[3]:
                    continue
                target_st, target_en = u[1], u[2]
                result[r][target_st:target_en + 1] = best[4]

    # Check for horizontal lines case (but not cross)
    elif len(h_lines) >= 2:
        h_lines_sorted = sorted(h_lines)

        # Find which region has most unique values
        region_data = []
        for i, h in enumerate(h_lines_sorted):
            if i == 0:
                region_data.append(('top', 0, h - 1))
            elif i == len(h_lines_sorted) - 1:
                region_data.append(('bottom', h + 1, rows - 1))
            else:
                region_data.append(('between', h_lines_sorted[i-1] + 1, h_lines_sorted[i] - 1))

        region_uniques = []
        for name, st, en in region_data:
            vals = [result[r][c] for r in range(st, en + 1) for c in range(cols)]
            unique_count = len(set(vals))
            region_uniques.append((unique_count, name, st, en))

        region_uniques.sort(key=lambda x: x[0], reverse=True)
        best = region_uniques[0]
        best_name, best_st, best_en = best[1], best[2], best[3]

        # Copy best region rows to all others
        best_rows = result[best_st:best_en + 1]  # Rows in best region
        target_rows = []
        for name, st, en in region_data:
            if name == best_name:
                continue
            target_rows.append((st, en, name))

        for t_st, t_en, t_name in target_rows:
            # Target rows range
            target_start = t_st
            target_end = t_en
            target_count = t_end - t_st + 1

            # Best rows might have different count than target
            # For now, just copy complete and wrap
            if len(best_rows) == target_count:
                for i, tr in enumerate(range(t_st, t_en + 1)):
                    result[tr] = list(best_rows[i])
            else:
                # Adjust based on patterns
                # This is complex - need actual demo data
                pass

    # Cross pattern (1 horizontal + 1 vertical)
    elif len(h_lines) == 1 and len(v_lines) == 1:
        h_line, v_line = h_lines[0], v_lines[0]

        tl_cells = [grid[r][c] for r in range(h_line) for c in range(v_line)]
        tl_w = v_line

        top_rows = range(h_line)
        bottom_rows = range(h_line + 1, rows)
        left_cols = range(v_line)
        right_cols = range(v_line + 1, cols)

        for r in top_rows:
            for c in right_cols:
                result[r][c] = tl_cells[r * tl_w + (c - (v_line + 1))]

        for r in bottom_rows:
            for c in left_cols:
                result[r][c] = tl_cells[(r - (h_line + 1)) * tl_w + c]

        for r in bottom_rows:
            for c in right_cols:
                result[r][c] = tl_cells[(r - (h_line + 1)) * tl_w + (c - (v_line + 1))]

    # Single horizontal line (like Demo 3)
    elif len(h_lines) == 1 and len(v_lines) == 0:
        h_line = h_lines[0]
        top_rows = list(range(h_line))
        bottom_rows = list(range(h_line + 1, rows))

        # Count unique in each region
        top_vals = [result[r][c] for r in top_rows for c in range(cols)]
        bottom_vals = [result[r][c] for r in bottom_rows for c in range(cols)]

        if len(set(bottom_vals)) >= len(set(top_vals)):
            # Copy bottom to top
            for i, r in enumerate(top_rows):
                result[r] = list(result[bottom_rows[i]])
            top_vals = [result[r][c] for r in top_rows for c in range(cols)]

        # Verify top now has more unique
        if len(set(bottom_vals)) >= len(set(top_vals)):
            # Copy bottom to top
            for i, r in enumerate(top_rows):
                result[r] = list(result[bottom_rows[i]])

    return result

